CREATE TABLE closed_sessions(session_id TEXT,canonical_id TEXT,tenant_id TEXT,start_time TIMESTAMP,end_time TIMESTAMP,duration_sec BIGINT,event_count BIGINT,pages TEXT[],event_types TEXT[],device_type TEXT,browser TEXT,country TEXT,window_start TIMESTAMP,window_end TIMESTAMP) WITH(connector='single_file',path='@INPUT@',format='json',type='source',wait_for_control='true');
CREATE TABLE result(session_id TEXT,canonical_id TEXT,tenant_id TEXT,start_time TEXT,end_time TEXT,duration_sec BIGINT,event_count BIGINT,pages TEXT[],event_types JSON,device_type TEXT,browser TEXT,country TEXT) WITH(connector='single_file',path='@OUTPUT@',format='json',type='sink');
CREATE VIEW expanded AS SELECT session_id,canonical_id,tenant_id,start_time,end_time,duration_sec,event_count,pages,device_type,browser,country,window_start,window_end,unnest(event_types) AS event_type FROM closed_sessions;
CREATE VIEW counts AS SELECT session_id,canonical_id,tenant_id,start_time,end_time,duration_sec,event_count,pages,device_type,browser,country,window_start,window_end,event_type,COUNT(*) AS n FROM expanded GROUP BY session_id,canonical_id,tenant_id,start_time,end_time,duration_sec,event_count,pages,device_type,browser,country,window_start,window_end,event_type;
CREATE VIEW fragments AS SELECT *,JSON_OBJECT(event_type VALUE n) AS fragment FROM counts;
INSERT INTO result SELECT session_id,canonical_id,tenant_id,to_char(start_time,'%Y-%m-%d %H:%M:%S%.3f') AS start_time,to_char(end_time,'%Y-%m-%d %H:%M:%S%.3f') AS end_time,duration_sec,event_count,array_sort(array_distinct(pages)) AS pages,JSON_QUERY(concat('{',STRING_AGG(substring(fragment FROM 2 FOR char_length(fragment)-2),',' ORDER BY event_type),'}'),'$') AS event_types,device_type,browser,country FROM fragments GROUP BY session_id,canonical_id,tenant_id,start_time,end_time,duration_sec,event_count,pages,device_type,browser,country,window_start,window_end;
